#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# Collects the facts about James's Mac that the callcontrol spikes depend on
# (issue #8) and writes them as a Markdown report to paste on the ticket.
# Run it ON THE MAC, with Teams and Stream Deck both running:
#
#   bash scripts/mac-facts-wizard.sh
#
# Manual answers are remembered in $ENV_FILE so a re-run only re-asks what
# you leave blank. The report lands in $REPORT_FILE and on the clipboard.

TOTAL_STAGES=9
ENV_FILE="${ENV_FILE:-$HOME/.callcontrol-mac-facts.env}"
REPORT_FILE="${REPORT_FILE:-$PWD/mac-facts.md}"
REPORT=""

# rec "line" appends a line to the report.
rec() { REPORT+="$1"$'\n'; }

# capture "command string" runs it, shows the output, records it as a fence.
capture() {
  local cmd="$1" out rc=0
  out=$(bash -c "$cmd" 2>&1) || rc=$?
  [[ -n "$out" ]] || out="(no output, exit $rc)"
  printf '  %s$ %s%s\n' "$DIM" "$cmd" "$RESET"
  printf '%s\n' "$out" | sed 's/^/    /'
  rec '```'; rec "\$ $cmd"; rec "$out"; rec '```'
}

# answer KEY "Label" "Prompt" asks, remembers the answer, records it.
answer() {
  local key="$1" label="$2" prompt="$3"
  ask "$key" "$prompt"
  write_env "$key" "${!key}"
  rec "- **$label:** ${!key:-(not answered)}"
}

banner "callcontrol: record the Mac environment (issue #8)"

if [[ "$(uname -s)" != "Darwin" ]]; then
  warn "This wizard reads facts from macOS. Run it on the Mac, not here."
  exit 1
fi

rec "## Mac environment for the spikes (issue #8)"
rec ""
rec "_Collected $(date '+%Y-%m-%d %H:%M %Z') by \`scripts/mac-facts-wizard.sh\`._"
rec ""

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "macOS version and CPU"
say "Reading the OS version and whether this is Apple Silicon or Intel."
rec "### 1. macOS and CPU"
capture "sw_vers"
capture "uname -m"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Teams version"
say "Reading the installed Teams bundle. If the path differs, type it when asked."
rec "### 2. Teams"
TEAMS_APP="/Applications/Microsoft Teams.app"
if [[ -d "$TEAMS_APP" ]]; then
  capture "defaults read '$TEAMS_APP/Contents/Info.plist' CFBundleShortVersionString"
  capture "defaults read '$TEAMS_APP/Contents/Info.plist' CFBundleIdentifier"
else
  warn "Teams not found at $TEAMS_APP."
  step "Open Teams → your avatar → About → Version, and copy the version."
  answer TEAMS_VERSION "Teams version (manual)" "Teams version:"
  answer TEAMS_PATH "Teams app path" "Where is Teams installed (full path, or blank if unsure)?"
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Stream Deck software and hardware"
say "Reading the Stream Deck app version and looking for the deck over USB."
rec "### 3. Stream Deck"
SD_APP="/Applications/Elgato Stream Deck.app"
if [[ -d "$SD_APP" ]]; then
  capture "defaults read '$SD_APP/Contents/Info.plist' CFBundleShortVersionString"
else
  warn "Stream Deck app not found at $SD_APP."
  step "Open Stream Deck → Preferences → General and read the version."
  answer SD_VERSION "Stream Deck software version (manual)" "Stream Deck version:"
fi
capture "system_profiler SPUSBDataType 2>/dev/null | grep -i -B2 -A6 'stream deck' | grep -iE 'stream deck|product id|vendor id|serial' || echo '(no Stream Deck found over USB)'"
step "Which deck is it? e.g. Stream Deck MK.2 (15 keys), Mini (6), XL (32), + (8 keys and 4 dials), Neo, Mobile."
answer SD_HARDWARE "Deck hardware" "Deck model and key count:"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Toolchain on the Mac"
say "Checking Node, Swift and the Xcode command line tools. Missing is a valid answer."
rec "### 4. Toolchain"
capture "command -v node && node --version || echo '(node missing)'"
capture "command -v swift && swift --version 2>&1 | head -2 || echo '(swift missing)'"
capture "xcode-select -p 2>&1 || echo '(no Xcode command line tools)'"
capture "command -v gh && gh --version | head -1 || echo '(gh missing)'"
capture "command -v streamdeck && streamdeck --version 2>&1 || echo '(streamdeck CLI missing)'"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Management and privacy policy"
say "Checking whether the Mac is under MDM, then whether you may grant Accessibility"
say "and Input Monitoring to a binary you built yourself."
rec "### 5. MDM and privacy grants"
capture "profiles status -type enrollment 2>&1"
capture "ls /Library/Managed\ Preferences 2>/dev/null || echo '(no managed preferences)'"
open_url "x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"
step "In Accessibility, press + and try to add any app (Terminal is fine; remove it afterwards)."
step "Does the toggle stick? Is anything greyed out or marked as managed by your organisation?"
answer AX_GRANT "Accessibility grant possible" "Could you add and enable an app under Accessibility? (yes / no / details):"
open_url "x-apple.systempreferences:com.apple.preference.security?Privacy_ListenEvent"
step "Same check under Input Monitoring."
answer IM_GRANT "Input Monitoring grant possible" "Could you add and enable an app under Input Monitoring? (yes / no / details):"
answer MDM_NOTE "MDM note" "Is this Mac employer-managed? Anything else about policy? (blank if nothing):"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Teams third-party app API setting"
say "The retired API used to appear as a Teams privacy setting. We expect it gone."
rec "### 6. Teams third-party app API"
open -a "Microsoft Teams" >/dev/null 2>&1 || true
step "In Teams: ... (top right) → Settings → Privacy. Look for 'Third-party app API' or 'Manage API'."
answer TEAMS_API_SETTING "Third-party app API in Teams Settings → Privacy" "Is it shown? (gone / present / details):"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Which app macOS holds responsible for plugin processes"
say "With Stream Deck running, listing its child processes and asking launchd which"
say "app is responsible for each. Research (#6) predicts Stream Deck.app."
rec "### 7. Responsible process for Stream Deck plugin children"
SD_PID=$(pgrep -x "Stream Deck" 2>/dev/null | head -1 || true)
if [[ -z "$SD_PID" ]]; then
  SD_PID=$(pgrep -f "Elgato Stream Deck.app/Contents/MacOS" 2>/dev/null | head -1 || true)
fi
if [[ -z "$SD_PID" ]]; then
  warn "Stream Deck does not seem to be running. Start it, then re-run this wizard."
  rec "- Stream Deck was not running when the wizard ran."
else
  rec "- Stream Deck pid: $SD_PID"
  capture "ps -axo pid,ppid,comm | awk -v p=$SD_PID '\$2==p'"
  CHILDREN=$(ps -axo pid,ppid | awk -v p="$SD_PID" '$2==p {print $1}')
  if [[ -z "$CHILDREN" ]]; then
    warn "No plugin child processes found. Install any Node plugin and re-run, or leave it for the spike."
    rec "- No child processes of Stream Deck found."
  fi
  for pid in $CHILDREN; do
    capture "ps -o pid,ppid,comm -p $pid | tail -1"
    capture "launchctl procinfo $pid 2>&1 | grep -iE 'responsible|^\s*path' || echo '(no responsible lines; full output may need sudo)'"
    GRANDCHILDREN=$(ps -axo pid,ppid | awk -v p="$pid" '$2==p {print $1}')
    for gpid in $GRANDCHILDREN; do
      say "grandchild $gpid (two-hop chain, the case the helper will be in):"
      capture "ps -o pid,ppid,comm -p $gpid | tail -1"
      capture "launchctl procinfo $gpid 2>&1 | grep -iE 'responsible|^\s*path' || echo '(no responsible lines)'"
    done
  done
  capture "pgrep -fl node || echo '(no node processes at all)'"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Teams UI language"
say "Label-based reading is language-dependent, so we record the language Teams shows."
rec "### 8. Languages"
capture "defaults read -g AppleLanguages 2>&1 | tr -d '\n' | tr -s ' '"
step "In Teams: Settings → Appearance and accessibility (or General) → Language."
answer TEAMS_LANGUAGE "Teams UI language" "Teams UI language (e.g. English (United Kingdom)):"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Write the report and post it on issue #8"
printf '%s' "$REPORT" > "$REPORT_FILE"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$REPORT_FILE"
if command -v pbcopy >/dev/null 2>&1; then
  pbcopy < "$REPORT_FILE" && note "Report copied to the clipboard."
fi
say "Read it over; remove anything you do not want on a public issue (serial numbers, hostnames)."
pause "Press Enter once you have checked $REPORT_FILE"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if confirm "Post $REPORT_FILE as a comment on J3tto/callcontrol#8 now?"; then
    gh issue comment 8 --repo J3tto/callcontrol --body-file "$REPORT_FILE" \
      && printf '  %s✓ posted%s on https://github.com/J3tto/callcontrol/issues/8\n' "$GREEN" "$RESET" \
      || SKIPPED+=("post $REPORT_FILE on issue #8 by hand")
  else
    SKIPPED+=("paste $REPORT_FILE (already on the clipboard) as a comment on https://github.com/J3tto/callcontrol/issues/8")
  fi
else
  open_url "https://github.com/J3tto/callcontrol/issues/8"
  SKIPPED+=("paste the clipboard (or $REPORT_FILE) as a comment on issue #8")
fi
# ──────────────────────────────────────────────────────────────────────────

finish
